'use strict';
let paymentUploadBusy=false,orderCountdown=null,orderRefreshGeneration=0;
const state={products:[],categories:[],banners:[],reviews:[],settings:{name:'YuuZ Market',description:'Akun game pilihan, belanja lebih nyaman.',advantages:['Transaksi Aman','Garansi Akun','Bantuan Admin'],warranty:'Hubungi admin untuk syarat garansi.',whatsapp:'',social:''},cart:[],orders:[],ready:false};
try{state.cart=JSON.parse(localStorage.getItem('yuuz_cart')||'[]').filter(x=>x&&typeof x.id==='string'&&Number.isInteger(x.qty)&&x.qty>0);}catch{state.cart=[];}
let bannerTimer=null,bannerController=null,channel=null,searchTimer=null;
const categoryName=id=>state.categories.find(c=>c.id===id)?.name||'Produk Digital';
const productImages=p=>[p.poster_url,...(p.product_images||[]).slice().sort((a,b)=>a.sort_order-b.sort_order).map(x=>x.url)].filter(Boolean);
const unitPrice=p=>p.sale_price??p.price;
const available=p=>p&&p.status==='active'&&p.stock>0;
function reconcile(){state.cart=state.cart.filter(x=>available(state.products.find(p=>p.id===x.id))).map(x=>({...x,qty:Math.min(x.qty,state.products.find(p=>p.id===x.id).stock)}));saveCart();}
function baseShell(){bannerController?.destroy();bannerController=null;clearInterval(bannerTimer);clearInterval(orderCountdown);orderRefreshGeneration++;const s=state.settings;$('#app').innerHTML=`<header class="topbar"><div class="wrap header"><a class="brand" href="#home">${imageTag(s.logo_url||'assets/logo.svg',s.name)}<span>${esc(s.name)}<small>GAME ACCOUNT STORE</small></span></a><div class="search">${icon('search')}<input id="search" aria-label="Cari produk" placeholder="Cari akun FF, ML..." value="${esc(new URLSearchParams(location.hash.split('?')[1]).get('q')||'')}"></div><a class="icon-btn" href="#cart" aria-label="Keranjang">${icon('cart')}<span class="count" data-count></span></a><a class="icon-btn" href="#orders" aria-label="Pesanan saya">${icon('user')}</a></div><nav class="nav-desktop">${nav()}</nav></header><main class="wrap content" id="page"></main><footer class="footer"><div class="wrap"><div><strong>${esc(s.name)}</strong><br>${esc(s.description)}</div><span>© ${new Date().getFullYear()} ${esc(s.name)} · Semua harga dalam Rupiah</span></div></footer><nav class="bottom-nav" aria-label="Navigasi utama">${nav()}</nav>`;$('#search').oninput=e=>{const v=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{location.hash='products?q='+encodeURIComponent(v);},650);};saveCart();}
function card(p){return `<article class="product"><a href="#product/${p.id}"><div class="product-poster">${imageTag(p.poster_url,p.name)}<span class="badge ${available(p)?'':'out'}">${available(p)?'Tersedia':'Stok Habis'}</span></div><div class="product-body"><small>${esc(categoryName(p.category_id))}</small><h3>${esc(p.name)}</h3>${p.sale_price!=null?`<del>${money(p.price)}</del>`:''}<div class="price">${money(unitPrice(p))}</div><span class="btn secondary wide">Lihat Detail ${icon('arrow',14)}</span></div></a></article>`;}
function productsGrid(list){return list.length?`<div class="product-grid">${list.map(card).join('')}</div>`:`<div class="empty">${icon('box',32)}<h3>Belum ada produk</h3><p class="muted">Produk akan tampil setelah diterbitkan oleh admin.</p></div>`;}
function categoryCard(c){return `<a href="#products?category=${c.id}" class="category"><span class="category-icon">${c.icon_url?imageTag(c.icon_url,c.name):icon(c.icon||'game',26)}</span><strong>${esc(c.name)}</strong></a>`;}
function baseHome(){const banners=state.banners.length?state.banners:[{image_url:'assets/banner-1.svg',link_url:'#products',title:'Selamat Datang di YuuZ Market'},{image_url:'assets/banner-2.svg',link_url:'#products',title:'Cari Akun FF atau ML Murah?'}];$('#page').innerHTML=`${!configured?setupHTML():''}<div class="store-intro"><div><span class="eyebrow">YUUZ MARKET / DIGITAL STORE</span><h1>Akun pilihan. Siap jadi andalan.</h1><p>Temukan akun favoritmu, periksa detailnya, belanja dengan nyaman.</p></div><a class="text-link intro-link" href="#help">${icon('shield',18)} Panduan Belanja</a></div><div class="hero" role="region" aria-roledescription="carousel" aria-label="Banner promosi"><div class="hero-track">${banners.map(b=>`<a class="hero-slide" href="${esc(b.link_url?.startsWith('#')?b.link_url:safeURL(b.link_url,'#products'))}" ${b.link_url?.startsWith('http')?'target="_blank" rel="noopener"':''}>${imageTag(b.image_url,b.title||'Promosi YuuZ Market')}</a>`).join('')}</div><button class="icon-btn hero-arrow prev" aria-label="Banner sebelumnya">${icon('left')}</button><button class="icon-btn hero-arrow next" aria-label="Banner selanjutnya">${icon('right')}</button></div><div class="dots">${banners.map((_,i)=>`<button class="dot ${i===0?'active':''}" data-slide="${i}" aria-label="Banner ${i+1}"></button>`).join('')}</div><div class="trust">${['shield','check','help'].map((ico,i)=>`<div>${icon(ico,24)}<div><strong>${esc(state.settings.advantages?.[i]||['Transaksi Aman','Garansi Akun','Bantuan Admin'][i])}</strong><small>Belanja dengan nyaman</small></div></div>`).join('')}</div><section class="section"><div class="section-head"><h2>Pilih Game Favoritmu</h2><a href="#categories" class="text-link">Lihat semua ${icon('arrow',16)}</a></div><div class="category-grid">${state.categories.map(categoryCard).join('')}${state.categories.length?'':'<p class="muted">Kategori belum tersedia.</p>'}</div></section><section class="section"><div class="section-head"><div><div class="eyebrow">FRESH STOCK</div><h2>Akun Terbaru</h2></div><a href="#products" class="text-link">Semua produk ${icon('arrow',16)}</a></div>${productsGrid(state.products.slice(0,8))}</section>${state.categories.filter(c=>/free fire|mobile legends/i.test(c.name)).map(c=>`<section class="section"><div class="section-head"><h2>Akun ${esc(c.name)}</h2><a class="text-link" href="#products?category=${c.id}">Lihat semua</a></div>${productsGrid(state.products.filter(p=>p.category_id===c.id).slice(0,4))}</section>`).join('')}<section class="section"><div class="section-head"><h2>Flash Sale</h2><a class="text-link" href="#products?sale=1">Lihat semua</a></div>${productsGrid(state.products.filter(p=>p.sale_price!=null).slice(0,4))}</section><section class="section"><h2>Rekomendasi</h2>${productsGrid(state.products.filter(p=>p.featured).slice(0,4))}</section>`;
bannerController=new YuuZCarousel($('.hero'),{interval:5000});}

function listPage(){const params=new URLSearchParams(location.hash.split('?')[1]),q=(params.get('q')||'').toLowerCase(),cat=params.get('category');let list=state.products.filter(p=>(!cat||p.category_id===cat)&&(!q||(p.name+' '+p.description+' '+categoryName(p.category_id)).toLowerCase().includes(q))&&(!params.has('sale')||p.sale_price!=null));$('#page').innerHTML=`<div class="section-head"><div><div class="eyebrow">PILIH AKUNMU</div><h1>${esc(cat?categoryName(cat):q?'Hasil pencarian':'Semua Produk')}</h1></div><select id="sort" aria-label="Urutkan produk" style="width:180px"><option value="new">Terbaru</option><option value="low">Harga terendah</option><option value="high">Harga tertinggi</option></select></div><div id="results">${productsGrid(list)}</div>`;$('#sort').onchange=e=>{const result=[...list];if(e.target.value!=='new')result.sort((a,b)=>(unitPrice(a)-unitPrice(b))*(e.target.value==='low'?1:-1));$('#results').innerHTML=productsGrid(result);};}
function baseAddCart(id,buy=false){const p=state.products.find(x=>x.id===id);if(!available(p))return toast('Stok tidak tersedia.');const x=state.cart.find(x=>x.id===id);if(x){if(!buy&&x.qty>=p.stock)return toast('Jumlah sudah mencapai stok tersedia.');if(!buy)x.qty++;}else state.cart.push({id,qty:1});saveCart();if(buy)location.hash='checkout';else toast('Produk ditambahkan ke keranjang.');}
function baseDetail(id){const p=state.products.find(x=>x.id===id);if(!p){$('#page').innerHTML='<div class="empty"><h2>Produk tidak ditemukan</h2><a href="#products" class="btn">Lihat produk</a></div>';return;}let n=0;const images=productImages(p);if(!images.length)images.push('assets/logo.svg');$('#page').innerHTML=`<a href="#products" class="text-link">${icon('left')} Kembali ke produk</a><div class="detail-grid section"><div><div class="gallery-main"><img id="main-image" src="${esc(safeURL(images[0],'assets/logo.svg'))}" alt="${esc(p.name)}"><div class="gallery-controls"><button class="icon-btn" id="photo-prev" aria-label="Foto sebelumnya">${icon('left')}</button><span class="gallery-count"></span><button class="icon-btn" id="photo-next" aria-label="Foto berikutnya">${icon('right')}</button></div></div><div class="thumbs">${images.map((u,i)=>`<button class="thumb ${i===0?'active':''}" data-photo="${i}" aria-label="Foto ${i+1}">${imageTag(u,'Foto '+(i+1))}</button>`).join('')}</div><p class="muted">Geser foto atau ketuk untuk membuka layar penuh.</p></div><div class="detail-info"><small>${esc(categoryName(p.category_id))}</small><h1>${esc(p.name)}</h1><span class="badge ${available(p)?'':'out'}">${available(p)?p.stock+' stok tersedia':'Stok Habis'}</span><div class="section">${p.sale_price!=null?`<del>${money(p.price)}</del>`:''}<div class="price">${money(unitPrice(p))}</div></div><h3>Detail Akun</h3><p class="details-text">${esc(p.details||'Lihat screenshot untuk detail akun.')}</p><h3>Deskripsi</h3><p class="details-text">${esc(p.description)}</p><div class="notice">${icon('shield',16)} ${esc(p.warranty||state.settings.warranty)}</div><div class="action-bar"><button id="add" class="btn secondary" ${available(p)?'':'disabled'}>${icon('cart')} Keranjang</button><button id="buy" class="btn" ${available(p)?'':'disabled'}>Beli Sekarang</button></div></div></div>`;const slide=i=>{n=(i+images.length)%images.length;$('#main-image').src=safeURL(images[n],'assets/logo.svg');$('.gallery-count').textContent=`${n+1} / ${images.length}`;$$('[data-photo]').forEach(e=>e.classList.toggle('active',+e.dataset.photo===n));};slide(0);$('#photo-prev').onclick=()=>slide(n-1);$('#photo-next').onclick=()=>slide(n+1);$$('[data-photo]').forEach(e=>e.onclick=()=>slide(+e.dataset.photo));bindSwipe($('.gallery-main'),d=>slide(n+d));$('#main-image').onclick=()=>{const d=modal(`<div class="lightbox">${imageTag(images[n],p.name)}</div><div class="row between"><button id="zoom-prev" class="btn secondary">${icon('left')}</button><span id="zoom-count"></span><button id="zoom" class="btn secondary">Zoom</button><button id="zoom-next" class="btn secondary">${icon('right')}</button></div>`);const show=i=>{slide(i);$('.lightbox img',d).src=safeURL(images[n],'assets/logo.svg');$('#zoom-count').textContent=`${n+1} / ${images.length}`;$('.lightbox').classList.remove('zoom');};show(n);$('#zoom-prev').onclick=()=>show(n-1);$('#zoom-next').onclick=()=>show(n+1);$('#zoom').onclick=()=>$('.lightbox').classList.toggle('zoom');bindSwipe($('.lightbox'),v=>show(n+v));d.onkeydown=e=>{if(e.key==='ArrowLeft')show(n-1);if(e.key==='ArrowRight')show(n+1);};};$('#add').onclick=()=>addCart(id);$('#buy').onclick=()=>addCart(id,true);}
function cartRows(edit=true){return state.cart.map(x=>{const p=state.products.find(p=>p.id===x.id);if(!p)return '';return `<div class="cart-item">${imageTag(p.poster_url,p.name)}<div><h3>${esc(p.name)}</h3><div class="price">${money(unitPrice(p))}</div><small>${edit?'Stok '+p.stock:'Jumlah '+x.qty}</small></div>${edit?`<div class="row"><input class="qty" type="number" min="1" max="${p.stock}" value="${x.qty}" data-qty="${p.id}" aria-label="Jumlah ${esc(p.name)}"><button class="icon-btn" data-remove="${p.id}" aria-label="Hapus produk">${icon('trash',16)}</button></div>`:money(x.qty*unitPrice(p))}</div>`;}).join('');}
const cartTotal=()=>state.cart.reduce((s,x)=>s+x.qty*unitPrice(state.products.find(p=>p.id===x.id)||{}),0);
function cart(){reconcile();$('#page').innerHTML=`<h1>Keranjang Belanja</h1>${state.cart.length?`<div class="panel">${cartRows()}<div class="row between section"><strong>Total</strong><span class="price">${money(cartTotal())}</span></div><a class="btn wide" href="#checkout">Lanjut Checkout ${icon('arrow')}</a></div>`:'<div class="empty"><h3>Keranjangmu masih kosong</h3><a class="btn" href="#products">Jelajahi Produk</a></div>'}`;$$('[data-qty]').forEach(e=>e.onchange=()=>{const p=state.products.find(x=>x.id===e.dataset.qty);state.cart.find(x=>x.id===p.id).qty=Math.max(1,Math.min(p.stock,Math.floor(+e.value)||1));saveCart();cart();});$$('[data-remove]').forEach(e=>e.onclick=()=>{state.cart=state.cart.filter(x=>x.id!==e.dataset.remove);saveCart();cart();});}
function whatsappLink(message){const n=String(state.settings.whatsapp||'').replace(/\D/g,'');return n?`https://wa.me/${n}?text=${encodeURIComponent(message)}`:'';}
function reviews(){ $('#page').innerHTML=`<h1>Testimoni Pelanggan</h1><p class="muted">Ulasan diterbitkan setelah ditinjau admin.</p><div class="grid2">${state.reviews.map(r=>`<article class="review"><div class="stars">${Array.from({length:r.rating},()=>icon('star',16)).join('')}</div><p class="details-text">${esc(r.body)}</p><strong>${esc(r.author)}</strong></article>`).join('')||'<div class="empty">Belum ada testimoni yang diterbitkan.</div>'}</div>`;}
function help(){const wa=whatsappLink('Halo admin YuuZ Market, saya perlu bantuan.');$('#page').innerHTML=`<h1>Bantuan & Garansi</h1><div class="grid2"><div class="panel"><h3>Cara Belanja</h3><ol><li>Pilih produk dan periksa screenshot akun.</li><li>Masukkan ke keranjang, isi nama dan WhatsApp.</li><li>Buat pesanan lalu hubungi admin dengan ID pesanan.</li><li>Pilih metode pembayaran, transfer sesuai total, dan kirim screenshot bukti dalam 24 jam.</li><li>Admin menyerahkan data akun setelah pembayaran dikonfirmasi.</li></ol><a class="text-link" href="#orders">Lihat Pesanan Saya ${icon('arrow')}</a></div><div class="panel"><h3>Informasi Garansi</h3><p class="details-text">${esc(state.settings.warranty)}</p>${wa?`<a href="${esc(wa)}" class="btn" target="_blank" rel="noopener">${icon('help')} Bantuan Admin</a>`:'<p class="muted">Kontak admin belum diatur.</p>'}${safeURL(state.settings.social)?`<p style="margin-top:16px"><a class="text-link" href="${esc(safeURL(state.settings.social))}" target="_blank" rel="noopener">Sosial Media ${icon('arrow')}</a></p>`:''}</div></div>`;}
window.addEventListener('hashchange',route);

// v2: methods, payment instructions, private proofs and database-synchronized deadlines.

async function loadData(){if(db){const [products,categories,banners,reviews,settings,methods]=await Promise.all([checked(db.from('products').select('*,product_images(*)').neq('status','draft').order('created_at',{ascending:false})),checked(db.from('categories').select('*').eq('active',true).order('sort_order')),checked(db.from('banners').select('*').eq('active',true).order('sort_order')),checked(db.from('reviews').select('*').eq('approved',true).order('created_at',{ascending:false})),checked(db.from('store_settings').select('*').eq('id',1).single()),checked(db.from('payment_methods').select('*').eq('is_active',true).order('sort_order'))]);Object.assign(state,{products,categories,banners,reviews,settings:{...state.settings,...settings.data},methods});await syncClock();}else state.methods=[];state.ready=true;state.loadError='';reconcile();}
function baseCheckout(){reconcile();if(!state.cart.length){cart();return;}const methods=state.methods||[];$('#page').innerHTML=`<h1>Checkout</h1><div class="notice">Harga dan stok diperiksa oleh database. Pembayaran baru dinyatakan terverifikasi setelah ACC admin.</div><div class="checkout-grid"><form class="panel" id="checkout-form"><h3>Informasi Pembeli</h3><label class="field"><span>Nama lengkap</span><input name="name" required minlength="2" maxlength="100" autocomplete="name"></label><label class="field"><span>Nomor WhatsApp</span><input name="phone" required pattern="[+0-9 ()-]{8,25}" placeholder="08xxxxxxxxxx" autocomplete="tel" type="tel"></label><h3>Metode Pembayaran</h3>${methods.map((m,i)=>`<label class="payment-choice"><input type="radio" name="method" value="${m.id}" required ${i===0?'checked':''}>${m.logo_url?imageTag(m.logo_url,m.name):icon(m.type==='qris'?'grid':'box',25)}<span><strong>${esc(m.name)}</strong><small>${esc(m.type==='qris'?'Scan QRIS':m.account_holder)}</small></span></label>`).join('')||'<div class="notice warning">Admin belum mengaktifkan metode pembayaran. Hubungi admin untuk informasi.</div>'}<p class="muted">Bayar dan kirim bukti dalam ${state.settings.payment_hours||24} jam sejak pesanan dibuat. Admin memeriksa bukti maksimal ${state.settings.verification_hours||24} jam setelah diterima.</p><button class="btn wide" type="submit" ${configured&&methods.length?'':'disabled'}>Buat Pesanan & Lanjut Bayar</button></form><div class="panel"><h3>Ringkasan Pesanan</h3>${cartRows(false)}<div class="row between section"><strong>Total</strong><span class="price">${money(cartTotal())}</span></div></div></div>`;$('#checkout-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);if(b.disabled)return;busy(b,true);try{await ensureSession();const f=new FormData(e.target),payload={name:f.get('name'),phone:f.get('phone'),method:f.get('method'),items:state.cart.map(x=>({product_id:x.id,quantity:x.qty}))};let stored;try{stored=JSON.parse(storageGet('sessionStorage','yuuz_checkout_v2')||'null');}catch{}const fingerprint=JSON.stringify(payload);if(!stored||stored.fingerprint!==fingerprint){stored={id:crypto.randomUUID(),fingerprint};storageSet('sessionStorage','yuuz_checkout_v2',JSON.stringify(stored));}const order=await checked(db.rpc('create_order',{p_request_id:stored.id,p_name:payload.name,p_phone:payload.phone,p_items:payload.items,p_payment_method_id:payload.method==='wallet'?null:payload.method}));state.cart=[];saveCart();storageRemove('sessionStorage','yuuz_checkout_v2');location.hash='order/'+order;}catch(err){fail(err);}finally{busy(b,false);}};}
function rawPaymentDestination(o){const m=o.payment_snapshot||{};return `<div class="payment-card-header">${m.logo_url?imageTag(m.logo_url,m.name):icon(m.type==='qris'?'grid':'box',28)}<div><strong>${esc(m.name||'Pembayaran Manual')}</strong><small style="display:block">Metode saat pesanan dibuat</small></div></div>${m.type==='qris'&&m.qr_image_url?`${imageTag(m.qr_image_url,'QRIS tujuan pembayaran','qr-image')}<button class="btn secondary wide" id="download-qr">${icon('image')} Download QRIS</button>`:`<div class="payment-destination" style="margin-top:16px"><small>Nomor rekening / e-wallet</small><div class="account-number">${esc(m.account_number||'Hubungi admin')}</div><p>Atas nama: ${esc(m.account_holder||'—')}</p>${m.account_number?'<button class="btn secondary" id="copy-account">Salin Nomor</button>':''}</div>`}<p class="details-text" style="margin-top:14px">${esc(m.instructions||'Transfer sesuai total, lalu kirim screenshot bukti pembayaran.')}</p>`;}
// Payment assets are shown only before the first submitted proof, while payable.
function paymentDestination(o){const proofs=listify(o.payment_proofs),payable=o.status==='pending'&&(!o.payment_status||['awaiting_payment','awaiting_proof'].includes(o.payment_status))&&!proofs.length&&!o.proof_retry_allowed&&new Date(o.payment_deadline).getTime()>serverNow();if(payable)return `<div class="active-payment" data-payment-until="${esc(o.payment_deadline)}">${rawPaymentDestination(o)}</div>`;return `<div class="payment-summary">${icon('shield',20)}<div><small>Metode pembayaran</small><strong>${esc(o.payment_snapshot?.name||'Pembayaran manual')}</strong><p>QRIS dan tujuan transfer ditutup. ${o.status==='verification'||o.payment_status==='awaiting_verification'?'Bukti diterima, menunggu ACC admin.':o.proof_retry_allowed?'Unggah ulang bukti sesuai catatan admin. Jangan transfer ulang tanpa konfirmasi admin.':'Lihat status transaksi di atas.'}</p></div></div>`;}
function receiptHTML(o,topup=false){if(topup?o.status!=='approved':o.payment_status!=='verified'||!['processing','completed'].includes(o.status))return '';const amount=topup?o.amount:o.total,stamp=o.payment_verified_at||o.reviewed_at;return `<section class="premium-receipt" aria-label="Struk transaksi"><div class="receipt-brand">${imageTag('assets/logo.svg','YuuZ Market')}<span>YUUZ MARKET<small>STRUK TRANSAKSI DIGITAL</small></span>${icon('check',26)}</div><div class="receipt-success">${icon('check',22)} ${topup?'Top Up Berhasil':o.status==='completed'?'Pesanan Selesai':'Pembayaran Berhasil'}</div><p class="receipt-caption">${topup?'Saldo telah ditambahkan ke YuuZ Wallet.':o.status==='completed'?'Terima kasih telah berbelanja di YuuZ Market.':'Pembayaran disetujui admin. Pesanan sedang diproses.'}</p><div class="receipt-amount">${money(amount)}</div><dl class="receipt-meta"><div><dt>ID transaksi</dt><dd>${esc(o.id)}</dd></div><div><dt>Waktu konfirmasi</dt><dd>${formatDate(stamp)}</dd></div><div><dt>Metode</dt><dd>${esc(o.payment_method==='wallet'?'YuuZ Wallet':o.payment_snapshot?.name||'Manual')}</dd></div><div><dt>Status</dt><dd>${topup?'Berhasil':statusLabels[o.status]}</dd></div></dl>${!topup?`<div class="receipt-items">${listify(o.order_items).map(i=>`<div><span>${esc(i.product_name)}<small>${i.quantity} × ${money(i.unit_price)}</small></span><strong>${money(i.quantity*i.unit_price)}</strong></div>`).join('')}</div>`:''}<div class="receipt-total"><span>Total ${topup?'saldo masuk':'pembayaran'}</span><strong>${money(amount)}</strong></div><div class="receipt-seal">${icon('shield',15)} Diverifikasi oleh Admin YuuZ Market</div></section>`;}
async function downloadQR(url){try{const response=await fetch(safeURL(url));if(!response.ok)throw Error('QRIS belum dapat diunduh.');const blob=await response.blob(),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='QRIS-YuuZMarket.'+(blob.type==='image/png'?'png':blob.type==='image/webp'?'webp':'jpg');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);}catch(e){fail(e);}}
function uploadProofXHR(file,path,onProgress){return new Promise(async(resolve,reject)=>{try{const {session}=await checked(db.auth.getSession());if(!session?.access_token)throw Error('Sesi pembeli berakhir.');const xhr=new XMLHttpRequest();xhr.open('POST',YUUZ_CONFIG.SUPABASE_URL.replace(/\/$/,'')+'/storage/v1/object/payment-proofs/'+path.split('/').map(encodeURIComponent).join('/'));xhr.setRequestHeader('Authorization','Bearer '+session.access_token);xhr.setRequestHeader('apikey',YUUZ_CONFIG.SUPABASE_ANON_KEY);xhr.setRequestHeader('Content-Type',file.type);xhr.setRequestHeader('x-upsert','false');xhr.timeout=120000;xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(Math.round(e.loaded/e.total*100));};xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300)resolve();else{let error;try{error=JSON.parse(xhr.responseText).message;}catch{}reject(Error(error||'Upload gagal. Periksa koneksi atau batas pembayaran.'));}};xhr.onerror=()=>reject(Error('Koneksi terputus saat upload.'));xhr.ontimeout=()=>reject(Error('Upload melewati batas waktu.'));xhr.send(file);}catch(e){reject(e);}});}
async function baseOrders(id){const generation=++orderRefreshGeneration;clearInterval(orderCountdown);$('#page').innerHTML='<div class="skeleton"></div>';try{await ensureSession();await syncClock();const data=await checked(db.from('orders').select('*,order_items(*),payment_proofs(*),order_status_history(*)').order('created_at',{ascending:false}));if(generation!==orderRefreshGeneration)return;state.orders=data;if(!id){$('#page').innerHTML=`<h1>Pesanan Saya</h1><p class="muted">Simpan ID pesanan. Riwayat ini terhubung dengan akun kamu.</p>${data.map(o=>`<a class="panel section" style="display:block" href="#order/${o.id}"><div class="row between"><strong class="order-title">${esc(o.id)}</strong><span class="badge ${o.payment_status==='rejected'?'rejected':''}">${paymentLabels[o.payment_status]||statusLabels[o.status]}</span></div><p style="margin-top:12px">${o.order_items.map(x=>esc(x.product_name)).join(', ')}</p><div class="row between"><span class="price">${money(o.total)}</span><small>${formatDate(o.created_at)}</small></div><span class="text-link">Lihat Pembayaran ${icon('arrow',16)}</span></a>`).join('')||'<div class="empty">Belum ada pesanan dalam sesi ini.</div>'}`;return;}const o=data.find(x=>x.id===id);if(!o){$('#page').innerHTML='<div class="empty"><h2>Pesanan tidak ditemukan dalam sesi ini</h2><a class="btn" href="#help">Hubungi Admin</a></div>';return;}const proofs=(o.payment_proofs||[]).slice().sort((a,b)=>new Date(b.uploaded_at)-new Date(a.uploaded_at)),latest=proofs[0],paying=o.status==='pending'&&['awaiting_payment','awaiting_proof','rejected'].includes(o.payment_status),canUpload=paying&&(o.payment_status!=='rejected'||o.proof_retry_allowed)&&new Date(o.payment_deadline).getTime()>serverNow();const wa=whatsappLink(`Halo Admin YuuZ Market, saya ingin menanyakan pesanan #${o.id}. Mohon dibantu pengecekannya.`);$('#page').innerHTML=`<a class="text-link" href="#orders">${icon('left')} Riwayat Pesanan</a><h1 style="margin-top:16px">Pembayaran & Status Pesanan</h1><p class="order-title">ID: <strong>${esc(o.id)}</strong></p><div class="status-chips"><span class="badge ${o.payment_status==='rejected'?'rejected':''}">${paymentLabels[o.payment_status]}</span><span class="badge">${statusLabels[o.status]}</span>${o.refund_status&&o.refund_status!=='none'?`<span class="badge warning">${refundLabels[o.refund_status]}</span>`:''}</div>${o.needs_followup?'<div class="notice warning" style="margin-top:16px">Pesanan ini perlu tindak lanjut admin. Hubungi admin untuk pemeriksaan lanjutan.</div>':''}${latest?.review_status==='rejected'?`<div class="notice rejected" style="margin-top:16px"><strong>Alasan Penolakan</strong><p class="details-text">${esc(latest.rejection_reason)}</p>${o.proof_retry_allowed?'Admin mengizinkan pengiriman ulang bukti sebelum batas waktu baru.':'Hubungi admin untuk tindak lanjut atau kesempatan unggah ulang.'}</div>`:''}<div class="order-layout section"><div class="panel"><h3>Detail Pesanan</h3><p>${esc(o.buyer_name)} · ${esc(o.phone)}</p>${o.order_items.map(i=>`<div class="cart-item">${imageTag(i.poster_url,i.product_name)}<div><h3>${esc(i.product_name)}</h3><small>${i.quantity} × ${money(i.unit_price)}</small></div><strong>${money(i.quantity*i.unit_price)}</strong></div>`).join('')}<div class="row between section"><strong>Total Pembayaran</strong><span class="price">${money(o.total)}</span></div>${paymentDestination(o)}${paying?`<div class="countdown"><p>Silakan selesaikan pembayaran dan unggah bukti transfer sebelum batas waktu berakhir.</p><strong id="payment-countdown"></strong><small>Batas pembayaran: ${formatDate(o.payment_deadline)}</small></div>`:''}${o.payment_status==='awaiting_verification'?`<div class="countdown"><p>Menunggu Verifikasi Admin</p><strong id="verification-countdown"></strong><small>Batas verifikasi: ${formatDate(o.verification_deadline)}</small></div>`:''}<div class="notice" style="margin-top:16px">${o.payment_status==='awaiting_verification'?'Pesanan kamu sedang diproses. Mohon tunggu verifikasi pembayaran maksimal 1 × 24 jam setelah bukti dikirim. Jika terdapat kendala pembayaran atau pesanan, silakan hubungi Admin YuuZ Market.':o.payment_status==='expired'?'Batas pembayaran telah berakhir. Stok dilepaskan oleh sistem. Hubungi admin jika kamu sudah melakukan transfer.':o.payment_status==='verified'?'Pembayaran telah diverifikasi admin. Periksa status pesanan atau hubungi admin untuk penyerahan akun.':'Pembayaran diverifikasi manual oleh admin. Upload screenshot tidak berarti pembayaran berhasil.'}</div>${wa?`<a class="btn wide" target="_blank" rel="noopener" href="${esc(wa)}">${icon('help')} Hubungi Admin</a>`:'<p class="muted">Nomor WhatsApp toko belum diatur.</p>'}</div><div><section class="panel"><h3>Bukti Transfer</h3>${canUpload?`<form id="proof-form"><p class="muted">Wajib screenshot JPG, PNG, atau WEBP maksimal 5 MB. Bukti hanya dapat dibuka oleh kamu dan admin.</p><label class="field"><span>Pilih / ganti screenshot</span><input id="proof-file" type="file" accept="image/jpeg,image/png,image/webp" required></label><div id="proof-preview"></div><button class="btn secondary" type="button" id="remove-proof" hidden>Hapus Sebelum Kirim</button><progress id="upload-progress" class="upload-progress" max="100" value="0" hidden></progress><p id="progress-label" class="muted"></p><button class="btn wide" id="send-proof" type="submit">Kirim Bukti Pembayaran</button><p id="proof-error" class="error-text"></p></form>`:`<p class="muted">${o.payment_status==='awaiting_verification'?'Bukti diterima. Tunggu pemeriksaan admin.':paying?'Batas waktu telah berakhir. Sistem sedang memperbarui status kedaluwarsa.':'Pengiriman bukti tidak tersedia untuk status ini.'}</p>`}<div id="sent-proofs" style="margin-top:20px">${proofs.map(p=>`<article style="margin-bottom:16px"><div class="row between"><span class="badge ${p.review_status==='rejected'?'rejected':''}">${{pending:'Menunggu Verifikasi',approved:'ACC',rejected:'Ditolak'}[p.review_status]}</span><small>${formatDate(p.uploaded_at)}</small></div><div class="preview-holder" data-proof-image="${p.id}"><button class="btn secondary wide" data-view-proof="${p.storage_path}">Buka Screenshot</button></div>${p.rejection_reason?`<p class="details-text">${esc(p.rejection_reason)}</p>`:''}</article>`).join('')||'<p class="muted">Belum ada bukti yang dikirim.</p>'}</div></section><section class="panel section"><h3>Riwayat Status</h3>${historyHTML(o.order_status_history)}</section></div></div>`;
if($('#copy-account'))$('#copy-account').onclick=async()=>{try{await navigator.clipboard.writeText(o.payment_snapshot.account_number);toast('Nomor disalin.');}catch{toast('Salin nomor yang ditampilkan secara manual.');}};if($('#download-qr'))$('#download-qr').onclick=()=>downloadQR(o.payment_snapshot.qr_image_url);$$('[data-view-proof]').forEach(b=>b.onclick=()=>openEvidence(b.dataset.viewProof));for(const p of proofs){try{const {signedUrl}=await checked(db.storage.from('payment-proofs').createSignedUrl(p.storage_path,300));if(generation!==orderRefreshGeneration)return;const holder=$(`[data-proof-image="${p.id}"]`);if(holder){holder.innerHTML=imageTag(signedUrl,'Bukti yang telah dikirim','evidence-preview')+`<button class="btn secondary" data-renew="${p.storage_path}">Buka / Perbarui Screenshot</button>`;$('img',holder).onclick=()=>openEvidence(p.storage_path);$('button',holder).onclick=()=>openEvidence(p.storage_path);}}catch(e){console.warn('Evidence preview unavailable',e);}}
const tick=()=>{if(generation!==orderRefreshGeneration)return;const p=$('#payment-countdown');if(p)p.textContent=timeRemaining(o.payment_deadline);const v=$('#verification-countdown');if(v)v.textContent=new Date(o.verification_deadline).getTime()<=serverNow()?'Perlu tindak lanjut admin':timeRemaining(o.verification_deadline);if($('#send-proof'))$('#send-proof').disabled=paymentUploadBusy||new Date(o.payment_deadline).getTime()<=serverNow();};tick();orderCountdown=setInterval(tick,1000);if(canUpload)bindProofForm(o);
}catch(e){if(generation!==orderRefreshGeneration)return;$('#page').innerHTML='<div class="empty"><h3>Pesanan belum dapat dimuat</h3><p>Periksa koneksi dan konfigurasi Supabase.</p></div>';fail(e);}}
function bindProofForm(o){let selected=null,previewURL=null,pendingSubmission=null;const input=$('#proof-file');const preview=()=>{$('#proof-preview').innerHTML=selected?'<img class="evidence-preview" alt="Preview bukti transfer">':'';if(selected)$('#proof-preview img').src=previewURL;$('#remove-proof').hidden=!selected;};input.onchange=async()=>{try{if(!input.files[0])return;await validateProofFile(input.files[0]);if(previewURL)URL.revokeObjectURL(previewURL);selected=input.files[0];previewURL=URL.createObjectURL(selected);pendingSubmission=null;preview();await checked(db.rpc('mark_transfer_started',{p_order_id:o.id}));}catch(e){selected=null;input.value='';preview();fail(e);}};$('#remove-proof').onclick=()=>{if(previewURL)URL.revokeObjectURL(previewURL);selected=null;previewURL=null;pendingSubmission=null;input.value='';preview();};$('#proof-form').onsubmit=async e=>{e.preventDefault();if(paymentUploadBusy)return;if(!selected)return toast('Pilih screenshot bukti transfer.');if(new Date(o.payment_deadline).getTime()<=serverNow())return toast('Batas pembayaran telah berakhir. Hubungi admin.');const button=$('#send-proof');paymentUploadBusy=true;busy(button,true,'Mengirim bukti…');input.disabled=true;$('#remove-proof').disabled=true;$('#upload-progress').hidden=false;try{await validateProofFile(selected);if(!pendingSubmission){const proofId=crypto.randomUUID(),ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[selected.type];pendingSubmission={id:proofId,path:`${(await checked(db.auth.getUser())).user.id}/${o.id}/${proofId}.${ext}`,uploaded:false};}if(!pendingSubmission.uploaded){await uploadProofXHR(selected,pendingSubmission.path,p=>{$('#upload-progress').value=p;$('#progress-label').textContent=`Mengunggah ${p}%`;});pendingSubmission.uploaded=true;}await checked(db.rpc('submit_payment_proof',{p_order_id:o.id,p_proof_id:pendingSubmission.id,p_storage_path:pendingSubmission.path}));toast('Bukti terkirim. Menunggu verifikasi admin.');if(previewURL)URL.revokeObjectURL(previewURL);paymentUploadBusy=false;await orders(o.id);}catch(err){if($('#proof-error'))$('#proof-error').textContent=err.message;fail(err);}finally{paymentUploadBusy=false;busy(button,false);if($('#proof-file'))$('#proof-file').disabled=false;if($('#remove-proof'))$('#remove-proof').disabled=false;}};}

// Refresh database time when returning to the app without discarding an upload.
document.addEventListener('visibilitychange',async()=>{if(document.hidden||!db)return;try{await syncClock();if(!paymentUploadBusy&&!$('#proof-file')?.files?.length&&location.hash.startsWith('#order/'))await orders(location.hash.split('/')[1]);}catch(e){console.warn(e);}});
// V4 account / wallet UI. Financial authority remains in protected PostgreSQL RPCs.
const account={user:null,profile:null,wallet:{balance:0,held_balance:0},notifications:[],topups:[],ledger:[],next:'#home',recovery:false};
let v4AuthChannel=null,v4RefreshTimer=null,activeUserHash='#home',galleryController=null;
const signedIn=()=>!!account.user&&!account.user.is_anonymous;
function requireLogin(next=location.hash||'#home'){if(signedIn())return true;account.next=next;location.hash='login';return false;}
function accountActive(){if(account.profile?.is_suspended){toast('Akun dinonaktifkan. Hubungi admin.');location.hash='profile';return false;}if(!account.profile?.terms_accepted_at&&account.profile?.role!=='admin'){toast('Lengkapi profil dan setujui syarat layanan.');location.hash='account-settings';return false;}return true;}
async function ensureSession(){if(!db)throw Error('Isi konfigurasi Supabase terlebih dahulu.');const {user}=await checked(db.auth.getUser());if(!user||user.is_anonymous)throw Error('Login dengan akun terdaftar diperlukan.');account.user=user;}
async function loadAccount(){if(!db)return;const {session}=await checked(db.auth.getSession());const user=session?.user;if(!user||user.is_anonymous){account.user=null;account.profile=null;account.wallet={balance:0,held_balance:0};account.notifications=[];account.ledger=[];account.topups=[];state.orders=[];state.cart=[];return;}const previous=account.user?.id;if(previous!==user.id){account.profile=null;account.wallet={balance:0,held_balance:0};account.notifications=[];account.ledger=[];account.topups=[];state.orders=[];state.cart=[];}account.user=user;const [profile,wallet,notifications]=await Promise.all([checked(db.from('profiles').select('*').eq('id',user.id).single()),checked(db.from('wallets').select('*').eq('user_id',user.id).single()),checked(db.from('notifications').select('*').eq('user_id',user.id).order('updated_at',{ascending:false}))]);Object.assign(account,{profile,wallet,notifications});if(previous!==user.id){try{state.cart=JSON.parse(storageGet('localStorage','yuuz_cart_'+user.id)||'[]').filter(x=>x&&typeof x.id==='string'&&Number.isInteger(x.qty)&&x.qty>0);}catch{state.cart=[];}}updateAccountBadges();}
function updateAccountBadges(){$$('[data-wallet-balance]').forEach(e=>e.textContent=money(account.wallet.balance));$$('[data-wallet-held]').forEach(e=>e.textContent=money(account.wallet.held_balance));$$('[data-unread]').forEach(e=>e.textContent=account.notifications.filter(n=>!n.read_at).length||'');}
function saveCart(){if(signedIn())storageSet('localStorage','yuuz_cart_'+account.user.id,JSON.stringify(state.cart));$$('[data-count]').forEach(e=>e.textContent=state.cart.reduce((s,x)=>s+x.qty,0)||'');}
function nav(){let path=(location.hash||'#home').split('/')[0].split('?')[0];if(['#topup-create','#wallet-history'].includes(path))path='#wallet';if(['#order','#topup','#orders'].includes(path))path='#transactions';if(path==='#account-settings')path='#profile';const items=[['home','home','Beranda'],['categories','grid','Kategori'],['wallet','wallet','Saldo'],['transactions','order','Transaksi'],['profile','user','Akun']];return items.map(([id,ico,label])=>`<a href="#${id}" class="${path==='#'+id?'active':''}">${icon(ico)}<span>${label}</span></a>`).join('');}
function shell(){galleryController?.destroy();galleryController=null;baseShell();const header=$('.header'),accountLink=$('a[aria-label="Pesanan saya"]',header);if(accountLink){accountLink.href='#profile';accountLink.setAttribute('aria-label',signedIn()?'Profil Akun':'Masuk Akun');}const button=document.createElement('a');button.className='icon-btn notification-link';button.href='#notifications';button.setAttribute('aria-label','Notifikasi');button.innerHTML=icon('bell')+'<span class="count" data-unread></span>';header.insertBefore(button,accountLink);header.insertAdjacentHTML('beforeend',themeButtonHTML());$('.nav-desktop').innerHTML=[['home','Beranda'],['categories','Kategori'],['products','Produk'],['wallet','Saldo'],['transactions','Transaksi'],['profile','Profil']].map(([id,label])=>`<a href="#${id}" class="${location.hash.split('?')[0]==='#'+id?'active':''}">${label}</a>`).join('');updateAccountBadges();}
function walletCard(){return `<div class="wallet-card"><div class="row between"><span class="wallet-kicker">${icon('wallet',18)} YUUZ WALLET</span><span class="wallet-chip">Saldo Internal</span></div><p>Saldo Tersedia</p><strong data-wallet-balance>${money(account.wallet.balance)}</strong><small>Ditahan untuk pesanan: <span data-wallet-held>${money(account.wallet.held_balance)}</span></small><div class="row wallet-actions"><a class="btn" href="#topup-create">${icon('plus',16)} Top Up</a><a class="btn wallet-ghost" href="#wallet-history">Riwayat</a><a class="wallet-link" href="#transactions">Lihat Transaksi ${icon('arrow',14)}</a></div></div>`;}
function home(){baseHome();const welcome=document.createElement('section');welcome.className='member-strip';welcome.innerHTML=signedIn()?`<div><span class="eyebrow">WELCOME BACK</span><h3>Halo, ${esc(account.profile?.username||'Player')}.</h3><p>Akun pilihanmu berikutnya menunggu.</p></div><a class="mini-wallet" href="#wallet">${icon('wallet',22)}<span><small>YuuZ Wallet</small><strong data-wallet-balance>${money(account.wallet.balance)}</strong></span>${icon('right',16)}</a>`:`<div><span class="eyebrow">YOUR NEXT LEVEL STARTS HERE</span><h3>Akun baru. Pengalaman baru.</h3><p>Buat akun untuk belanja dan menikmati YuuZ Wallet.</p></div><a class="btn" href="#register">Daftar Akun ${icon('arrow',16)}</a>`;$('.store-intro').after(welcome);}
function addCart(id,buy=false){if(!requireLogin('#product/'+id)||!accountActive())return;baseAddCart(id,buy);}
function authInput(label,name,type='text',extra=''){return `<label class="field"><span>${label}</span><div class="password-field"><input name="${name}" type="${type}" ${extra}>${type==='password'?`<button type="button" class="password-toggle" data-password="${name}" aria-label="Tampilkan password">${icon('eye',17)}</button>`:''}</div></label>`;}
function bindPasswordToggles(root){$$('[data-password]',root).forEach(b=>b.onclick=()=>{const input=$(`[name="${b.dataset.password}"]`,root),visible=input.type==='password';input.type=visible?'text':'password';b.innerHTML=icon(visible?'eye-off':'eye',17);b.setAttribute('aria-label',visible?'Sembunyikan password':'Tampilkan password');});}
function validatePassword(a,b){if(a!==b)throw Error('Konfirmasi password belum cocok.');if(a.length<8||!/[a-z]/i.test(a)||!/[0-9]/.test(a))throw Error('Password minimal 8 karakter, mengandung huruf dan angka.');}
function authPage(mode){const register=mode==='register',forgot=mode==='forgot',reset=mode==='reset-password';const title=register?'Mulai perjalananmu.':forgot?'Lupa password?':reset?'Buat password baru.':'Selamat datang kembali.';$('#page').innerHTML=`<div class="auth-layout"><div class="auth-visual"><span class="eyebrow">YUUZ MARKET / MEMBER AREA</span><h2>Level up<br>your next game.</h2><p>Temukan akun pilihan, simpan saldo dengan nyaman, dan pantau setiap transaksi dalam satu tempat.</p><div class="auth-art">${imageTag('assets/logo.svg','YuuZ Market')}<span class="art-pill">${icon('shield')} Admin Approved</span><span class="art-pill second">${icon('wallet')} YuuZ Wallet</span></div><small>Belanja akun game, lebih teratur.</small></div><form class="auth-form" id="user-auth"><div class="eyebrow">${register?'CREATE ACCOUNT':forgot||reset?'ACCOUNT RECOVERY':'MEMBER SIGN IN'}</div><h1>${title}</h1><p class="muted">${register?'Daftar sekali untuk mengakses wallet dan transaksi.':forgot?'Masukkan email akun untuk meminta tautan reset.':reset?'Gunakan password kuat untuk melindungi akunmu.':'Masuk dengan email dan password akun terdaftar.'}</p>${!configured?setupHTML():''}${register?authInput('Username','username','text','required pattern="[A-Za-z][A-Za-z0-9_]{2,23}" minlength="3" maxlength="24" autocomplete="username"')+authInput('Nomor WhatsApp','whatsapp','tel','required pattern="[+0-9 ()-]{8,25}" autocomplete="tel"'):''}${!reset?authInput('Email','email','email','required autocomplete="email"'):''}${!forgot?authInput('Password','password','password',`required minlength="8" autocomplete="${register||reset?'new-password':'current-password'}"`):''}${register||reset?authInput('Konfirmasi Password','confirm','password','required minlength="8" autocomplete="new-password"'):''}${register?'<label class="terms-check"><input name="terms" type="checkbox" required><span>Saya menyetujui <a href="#terms" target="_blank" rel="noopener">syarat layanan</a> YuuZ Market.</span></label>':''}<p class="error-text" id="auth-error" role="alert"></p><button type="submit" class="btn wide" ${configured?'':'disabled'}>${register?'Daftar Akun':forgot?'Kirim Tautan Reset':reset?'Simpan Password Baru':'Masuk'}</button><div class="auth-links">${register?'<span>Sudah punya akun? <a href="#login">Masuk</a></span>':forgot||reset?'<a href="#login">Kembali ke Login</a>':'<span>Belum punya akun? <a href="#register">Daftar Akun</a></span><a href="#forgot">Lupa Password</a>'}</div></form></div>`;const form=$('#user-auth');bindPasswordToggles(form);form.onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',form);if(b.disabled)return;busy(b,true);$('#auth-error').textContent='';try{const f=new FormData(form),email=String(f.get('email')||'').trim(),pass=String(f.get('password')||'');const root=location.origin+location.pathname;
if(register){validatePassword(pass,f.get('confirm'));if(!f.has('terms'))throw Error('Setujui syarat layanan terlebih dahulu.');const username=f.get('username').trim().toLowerCase();if(!await checked(db.rpc('username_available',{p_username:username})))throw Error('Username tidak tersedia. Pilih username lain.');const result=await checked(db.auth.signUp({email,password:pass,options:{data:{username,whatsapp:f.get('whatsapp'),tos_accepted:true},emailRedirectTo:root}}));if(result.session){await loadAccount();location.hash=account.next||'#profile';}else{modal('<h2>Periksa Email Kamu</h2><p>Jika pendaftaran dapat diproses, tautan verifikasi dikirim ke email tersebut. Buka tautan lalu login. Bila akun sudah terdaftar, gunakan Login atau Lupa Password.</p><a class="btn" href="#login" onclick="document.getElementById(\'modal\').close()">Ke Login</a>');}}
else if(forgot){await checked(db.auth.resetPasswordForEmail(email,{redirectTo:root+'?flow=recovery'}));$('#auth-error').classList.remove('error-text');$('#auth-error').textContent='Jika email terdaftar, tautan reset akan dikirim. Periksa inbox dan spam.';}
else if(reset){validatePassword(pass,f.get('confirm'));if(!signedIn()||!account.recovery)throw Error('Buka tautan pemulihan yang valid dari email terlebih dahulu.');await checked(db.auth.updateUser({password:pass}));account.recovery=false;history.replaceState(null,'',location.pathname+'#profile');await loadAccount();await route();toast('Password diperbarui.');}
else{try{await checked(db.auth.signInWithPassword({email,password:pass}));}catch{throw Error('Email/password tidak cocok atau email belum diverifikasi. Periksa kembali atau gunakan Lupa Password.');}await loadAccount();if(!signedIn())throw Error('Login akun terdaftar diperlukan.');location.hash=account.next||'#profile';}
}catch(err){$('#auth-error').textContent=err.message;}finally{busy(b,false);}};}
function profilePage(){const p=account.profile||{};$('#page').innerHTML=`<section class="profile-hero"><div class="profile-identity">${imageTag(p.avatar_url||'assets/logo.svg','Avatar','avatar')}<div><span class="eyebrow">MY YUUZ ACCOUNT</span><h1>${esc(p.username||'Lengkapi Profil')}</h1><p>${esc(account.user.email)}</p><small>${esc(p.whatsapp||'WhatsApp belum diisi')}</small></div></div><a class="btn secondary" href="#account-settings">${icon('settings',16)} Pengaturan Akun</a></section>${p.is_suspended?`<div class="notice rejected">Akun dinonaktifkan: ${esc(p.suspension_reason)}. Hubungi admin untuk tindak lanjut.</div>`:''}${!p.terms_accepted_at&&p.role!=='admin'?'<div class="notice warning">Lengkapi username, WhatsApp, dan persetujuan layanan pada Pengaturan Akun sebelum transaksi.</div>':''}<div class="account-grid">${walletCard()}<div class="panel account-menu"><a href="#transactions?tab=orders">${icon('order')} Riwayat Pembelian ${icon('right',16)}</a><a href="#transactions?tab=topups">${icon('plus')} Riwayat Top Up ${icon('right',16)}</a><a href="#notifications">${icon('bell')} Notifikasi ${icon('right',16)}</a><a href="#help">${icon('help')} Bantuan Admin ${icon('right',16)}</a><button id="user-logout">${icon('logout')} Logout</button></div></div>`;$('#user-logout').onclick=async()=>{try{await checked(db.auth.signOut());account.user=null;account.profile=null;account.wallet={balance:0,held_balance:0};account.notifications=[];account.ledger=[];account.topups=[];state.orders=[];state.cart=[];location.hash='login';await route();}catch(e){fail(e);}};}
function accountSettings(){const p=account.profile||{};$('#page').innerHTML=`<h1>Pengaturan Akun</h1><form id="profile-form" class="panel profile-form">${authInput('Username','username','text',`required pattern="[A-Za-z][A-Za-z0-9_]{2,23}" maxlength="24" value="${esc(p.username?.length<=24?p.username:'')}"`)}${authInput('Nomor WhatsApp','whatsapp','tel',`required pattern="[+0-9 ()-]{8,25}" value="${esc(p.whatsapp)}"`)}<label class="field"><span>Email</span><input value="${esc(account.user.email)}" disabled></label><label class="field"><span>Avatar PNG/JPG/WebP maksimal 2 MB</span><input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="terms-check"><input name="terms" type="checkbox" required ${p.terms_accepted_at?'checked':''}><span>Saya menyetujui <a href="#terms" target="_blank" rel="noopener">syarat layanan</a>.</span></label><button type="submit" class="btn">Simpan Profil</button></form><form id="change-password" class="panel profile-form section"><h3>Ganti Password</h3>${authInput('Password saat ini','current','password','required autocomplete="current-password"')}${authInput('Password baru','password','password','required minlength="8" autocomplete="new-password"')}${authInput('Konfirmasi password baru','confirm','password','required minlength="8" autocomplete="new-password"')}<button type="submit" class="btn secondary">Perbarui Password</button></form>`;bindPasswordToggles($('#page'));$('#profile-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);busy(b,true);try{const f=new FormData(e.target);let avatar=p.avatar_url||null;const file=$('#avatar-file').files[0];if(file){await validateProofFile(file);if(file.size>2097152)throw Error('Avatar maksimal 2 MB.');const ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[file.type],path=account.user.id+'/'+crypto.randomUUID()+'.'+ext;await checked(db.storage.from('avatars').upload(path,file,{contentType:file.type,upsert:false}));avatar=db.storage.from('avatars').getPublicUrl(path).data.publicUrl;}await checked(db.rpc('update_my_profile',{p_username:f.get('username'),p_whatsapp:f.get('whatsapp'),p_avatar_url:avatar,p_accept_terms:f.has('terms')}));await loadAccount();toast('Profil disimpan.');location.hash='profile';}catch(err){fail(err);}finally{busy(b,false);}};$('#change-password').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);busy(b,true);try{const f=new FormData(e.target);validatePassword(f.get('password'),f.get('confirm'));await checked(db.auth.signInWithPassword({email:account.user.email,password:f.get('current')}));await checked(db.auth.updateUser({password:f.get('password')}));e.target.reset();toast('Password berhasil diganti.');}catch(err){fail(err);}finally{busy(b,false);}};}
async function walletPage(historyOnly=false){await loadAccount();const ledger=await checked(db.from('wallet_transactions').select('*').eq('user_id',account.user.id).order('created_at',{ascending:false}));account.ledger=ledger;$('#page').innerHTML=`<div class="section-head"><div><span class="eyebrow">YOUR BALANCE, YOUR NEXT LEVEL</span><h1>${historyOnly?'Riwayat Wallet':'YuuZ Wallet'}</h1></div><a class="text-link" href="#transactions">Semua Transaksi ${icon('arrow',16)}</a></div>${walletCard()}<p class="wallet-disclaimer">Saldo hanya untuk belanja di YuuZ Market. Tidak dapat ditransfer antar pengguna atau ditarik tunai.</p><section class="section panel"><h3>Aktivitas Saldo</h3>${ledger.length?ledger.map(x=>`<div class="ledger-row"><span class="ledger-icon">${icon(x.kind==='topup'||x.kind==='refund'?'plus':'wallet',19)}</span><div><strong>${{topup:'Top Up Disetujui',hold:'Saldo Ditahan',capture:'Pembelian Disetujui',release:'Saldo Dikembalikan',refund:'Refund ke Saldo'}[x.kind]}</strong><small>${formatDate(x.created_at)}</small><small>${esc(x.notes)}</small></div><div class="ledger-amount ${x.delta_available>0?'positive':''}"><strong>${x.kind==='capture'?'-'+money(x.amount):(x.delta_available>0?'+':'')+money(x.delta_available)}</strong><small>Ditahan: ${x.delta_held>0?'+':''}${money(x.delta_held)}</small></div></div>`).join(''):'<div class="empty">Belum ada aktivitas saldo. Top up pertama kamu akan tercatat di sini setelah ACC admin.</div>'}</section>`;}
function methodOptions(includeWallet=false){return `${includeWallet?`<label class="payment-choice"><input type="radio" name="method" value="wallet" checked>${icon('wallet',26)}<span><strong>YuuZ Wallet</strong><small>Saldo tersedia: ${money(account.wallet.balance)} · Menunggu ACC admin</small></span></label>`:''}${(state.methods||[]).map((m,i)=>`<label class="payment-choice"><input type="radio" name="method" value="${m.id}" ${!includeWallet&&i===0?'checked':''} required>${m.logo_url?imageTag(m.logo_url,m.name):icon(m.type==='qris'?'grid':'box',25)}<span><strong>${esc(m.name)}</strong><small>${esc(m.type==='qris'?'Scan QRIS':m.account_holder)}</small></span></label>`).join('')}`;}
function checkout(){if(!requireLogin('#checkout')||!accountActive())return;baseCheckout();const form=$('#checkout-form');if(!form)return;$('input[name=name]',form).value=account.profile?.username||'';$('input[name=phone]',form).value=account.profile?.whatsapp||'';$$('.payment-choice',form).forEach(x=>x.remove());$$('.notice.warning',form).forEach(x=>x.remove());const h=[...form.querySelectorAll('h3')].find(x=>x.textContent.includes('Metode'));h.insertAdjacentHTML('afterend',methodOptions(true));$('button[type=submit]',form).disabled=!configured;const originalSubmit=form.onsubmit;form.onsubmit=async e=>{if(new FormData(form).get('method')==='wallet'&&cartTotal()>+account.wallet.balance){e.preventDefault();toast('Saldo tersedia belum mencukupi. Top up atau pilih pembayaran manual.');return;}await originalSubmit(e);};}
function topupCreate(){if(!accountActive())return;$('#page').innerHTML=`<div class="section-head"><div><span class="eyebrow">ADD CREDIT</span><h1>Top Up YuuZ Wallet</h1></div><a href="#wallet" class="text-link">Kembali ke Saldo</a></div><div class="checkout-grid"><form class="panel" id="topup-form"><h3>Berapa saldo yang ingin ditambahkan?</h3>${authInput('Nominal top up (Rp)','amount','number','required min="1000" max="100000000" step="1" placeholder="Contoh: 100000"')}<div class="quick-amounts">${[25000,50000,100000,250000].map(n=>`<button class="btn secondary" type="button" data-amount="${n}">${money(n)}</button>`).join('')}</div><h3>Metode Pembayaran</h3>${methodOptions()||'<div class="notice warning">Metode pembayaran belum tersedia. Hubungi admin.</div>'}<button class="btn wide" type="submit" ${(state.methods||[]).length?'':'disabled'}>Buat Permintaan Top Up</button></form><div>${walletCard()}<div class="notice" style="margin-top:20px">Transfer sesuai nominal dan kirim screenshot bukti dalam batas waktu. Saldo bertambah setelah admin mencocokkan penerimaan dana dan menekan ACC.</div></div></div>`;$$('[data-amount]').forEach(b=>b.onclick=()=>$('#topup-form [name=amount]').value=b.dataset.amount);$('#topup-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);if(b.disabled)return;busy(b,true);try{await ensureSession();const f=new FormData(e.target),amount=+f.get('amount'),method=f.get('method'),key=JSON.stringify({amount,method});let saved;try{saved=JSON.parse(storageGet('sessionStorage','yuuz_topup')||'null');}catch{}if(!saved||saved.key!==key){saved={id:crypto.randomUUID(),key};storageSet('sessionStorage','yuuz_topup',JSON.stringify(saved));}const id=await checked(db.rpc('create_topup',{p_id:saved.id,p_amount:amount,p_method:method}));storageRemove('sessionStorage','yuuz_topup');location.hash='topup/'+id;}catch(err){fail(err);}finally{busy(b,false);}};}
async function transactions(){const [orders,topups]=await Promise.all([checked(db.from('orders').select('*,order_items(*)').eq('customer_id',account.user.id).order('created_at',{ascending:false})),checked(db.from('topup_requests').select('*').eq('customer_id',account.user.id).order('created_at',{ascending:false}))]);const entries=[...orders.map(o=>({...o,kind:'order',amount:o.total,label:o.order_items.map(i=>i.product_name).join(', ')})),...topups.map(t=>({...t,kind:'topup',label:'Top Up YuuZ Wallet'}))].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const initial=new URLSearchParams(location.hash.split('?')[1]).get('tab')||'all';$('#page').innerHTML=`<span class="eyebrow">EVERY MOVE, ALL IN ONE PLACE</span><h1>Transaksi Saya</h1><div class="tabs" id="transaction-tabs">${[['all','Semua'],['orders','Pembelian'],['topups','Top Up Saldo']].map(([v,l])=>`<button data-tab="${v}" class="${v===initial?'active':''}">${l}</button>`).join('')}</div><div id="transaction-list"></div>`;const show=tab=>{$('#transaction-list').innerHTML=entries.filter(x=>tab==='all'||tab==='orders'&&x.kind==='order'||tab==='topups'&&x.kind==='topup').map(x=>`<a class="transaction-card" href="#${x.kind}/${x.id}"><span class="transaction-icon">${icon(x.kind==='topup'?'wallet':'box',24)}</span><div><small>${x.kind==='topup'?'TOP UP SALDO':'PEMBELIAN'}</small><h3>${esc(x.label)}</h3><small>${formatDate(x.created_at)} · ${esc(x.id.slice(0,8))}</small></div><div><strong>${money(x.amount)}</strong><span class="badge ${x.status==='rejected'||x.payment_status==='rejected'?'rejected':''}">${x.kind==='topup'?topupLabels[x.status]:(['processing','completed','expired','cancelled','rejected'].includes(x.status)?statusLabels[x.status]:paymentLabels[x.payment_status]||statusLabels[x.status])}</span></div></a>`).join('')||'<div class="empty">Belum ada transaksi di kategori ini.</div>';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));};show(initial);$$('[data-tab]').forEach(b=>b.onclick=()=>show(b.dataset.tab));}
async function orders(id){if(!requireLogin(id?'#order/'+id:'#transactions'))return;if(!id)return transactions();const o=await checked(db.from('orders').select('*,order_items(*),wallet_holds(*),order_status_history(*)').eq('id',id).eq('customer_id',account.user.id).single());if(o.payment_method!=='wallet'){await baseOrders(id);const panel=$('#page .order-layout > .panel');if(panel)panel.insertAdjacentHTML('afterbegin',receiptHTML(o));return;}$('#page').innerHTML=`<a class="text-link" href="#transactions">${icon('left')} Transaksi Saya</a><h1 class="section">Pembelian dengan YuuZ Wallet</h1><div class="order-layout"><div class="panel">${receiptHTML(o)}<p class="order-title">ID: ${esc(o.id)}</p><div class="status-chips"><span class="badge ${o.payment_status==='rejected'?'rejected':''}">${paymentLabels[o.payment_status]}</span><span class="badge">${statusLabels[o.status]}</span></div>${o.order_items.map(i=>`<div class="cart-item">${imageTag(i.poster_url,i.product_name)}<div><h3>${esc(i.product_name)}</h3><small>${i.quantity} × ${money(i.unit_price)}</small></div><strong>${money(i.quantity*i.unit_price)}</strong></div>`).join('')}<div class="row between section"><strong>Total</strong><span class="price">${money(o.total)}</span></div><div class="notice">${o.payment_status==='awaiting_approval'?'Saldo dan stok ditahan sementara. Pembelian belum berhasil sampai admin menekan ACC.':o.status==='rejected'?'Pembelian ditolak. Saldo yang ditahan sudah kembali ke saldo tersedia.':o.payment_status==='verified'?'Pembelian disetujui admin. Data akun diserahkan secara pribadi oleh admin.':'Periksa status pesanan atau hubungi admin.'}</div>${o.rejection_reason?`<div class="notice rejected">${esc(o.rejection_reason)}</div>`:''}${o.needs_followup?'<div class="notice warning">Verifikasi melewati target waktu. Hubungi admin untuk tindak lanjut.</div>':''}${adminContact(o.id)}</div><div><div class="panel"><h3>Status Saldo Ditahan</h3>${listify(o.wallet_holds).map(h=>`<p>${money(h.amount)} · ${{held:'Menunggu ACC',captured:'Pembayaran Final',released:'Dikembalikan'}[h.status]}</p>`).join('')}</div><div class="panel section"><h3>Riwayat Status</h3>${historyHTML(o.order_status_history)}</div></div></div>`;}
function adminContact(id){const url=whatsappLink(`Halo Admin YuuZ Market, saya ingin menanyakan transaksi #${id}. Mohon dibantu pengecekannya.`);return url?`<a class="btn wide" href="${esc(url)}" target="_blank" rel="noopener">${icon('help',18)} Hubungi Admin</a>`:'<p class="muted">Kontak admin belum diatur.</p>';}
function proofFormHTML(){return `<form id="proof-form"><p class="muted">JPG, PNG, atau WEBP maksimal 5 MB. Bukti tidak membuat saldo otomatis bertambah.</p><label class="field"><span>Pilih / ganti screenshot</span><input id="proof-file" type="file" accept="image/png,image/jpeg,image/webp" required></label><div id="proof-preview"></div><button type="button" class="btn secondary" id="remove-proof" hidden>Hapus Sebelum Kirim</button><progress class="upload-progress" id="upload-progress" value="0" max="100" hidden></progress><p id="progress-label" class="muted"></p><button class="btn wide" id="send-proof">Kirim Bukti</button><p id="proof-error" class="error-text"></p></form>`;}
async function topupDetail(id){await syncClock();const t=await checked(db.from('topup_requests').select('*,payment_proofs(*),transaction_status_history(*)').eq('id',id).eq('customer_id',account.user.id).single());const canUpload=t.status==='pending'&&new Date(t.payment_deadline).getTime()>serverNow();$('#page').innerHTML=`<a class="text-link" href="#transactions?tab=topups">${icon('left')} Riwayat Top Up</a><h1 class="section">Top Up YuuZ Wallet</h1><div class="order-layout"><div class="panel">${receiptHTML(t,true)}<p class="order-title">ID: ${esc(t.id)}</p><span class="badge ${t.status==='rejected'?'rejected':''}">${topupLabels[t.status]}</span><div class="row between section"><strong>Nominal Top Up</strong><span class="price">${money(t.amount)}</span></div>${paymentDestination(t)}${t.status==='pending'?`<div class="countdown"><p>Kirim bukti sebelum batas pembayaran.</p><strong id="payment-countdown">${timeRemaining(t.payment_deadline)}</strong><small>${formatDate(t.payment_deadline)}</small></div>`:''}${t.status==='verification'?`<div class="notice">Bukti sudah diterima. Tunggu ACC admin maksimal 1 × 24 jam sejak bukti dikirim. Saldo belum bertambah sampai disetujui.</div><p class="deadline-meta">Batas verifikasi: ${formatDate(t.verification_deadline)}</p>`:''}${t.status==='approved'?'<div class="notice">Top up berhasil. Saldo sudah ditambahkan ke YuuZ Wallet.</div>':''}${t.rejection_reason?`<div class="notice rejected"><strong>Catatan Admin</strong><p>${esc(t.rejection_reason)}</p>${t.proof_retry_allowed?'Kamu dapat mengirim bukti baru sebelum batas waktu baru.':''}</div>`:''}${t.needs_followup?'<div class="notice warning">Perlu tindak lanjut admin. Hubungi admin untuk memeriksa transaksi.</div>':''}${adminContact(t.id)}</div><div><section class="panel"><h3>Bukti Transfer</h3>${canUpload?proofFormHTML():''}${(t.payment_proofs||[]).map(p=>`<article class="proof-history"><span class="badge">${{pending:'Menunggu ACC',approved:'ACC',rejected:'Ditolak'}[p.review_status]}</span><small>${formatDate(p.uploaded_at)}</small><button class="btn secondary wide" data-topup-proof="${p.storage_path}">Buka Screenshot / Zoom</button>${p.rejection_reason?`<p>${esc(p.rejection_reason)}</p>`:''}</article>`).join('')||(!canUpload?'<p class="muted">Belum ada bukti.</p>':'')}</section><section class="panel section"><h3>Riwayat Status</h3>${historyHTML(t.transaction_status_history)}</section></div></div>`;if($('#copy-account'))$('#copy-account').onclick=async()=>{try{await navigator.clipboard.writeText(t.payment_snapshot.account_number);toast('Nomor disalin.');}catch{toast('Salin nomor tujuan secara manual.');}};if($('#download-qr'))$('#download-qr').onclick=()=>downloadQR(t.payment_snapshot.qr_image_url);$$('[data-topup-proof]').forEach(b=>b.onclick=()=>openEvidence(b.dataset.topupProof));clearInterval(orderCountdown);orderCountdown=setInterval(()=>{const c=$('#payment-countdown');if(c)c.textContent=timeRemaining(t.payment_deadline);const b=$('#send-proof');if(b)b.disabled=paymentUploadBusy||new Date(t.payment_deadline).getTime()<=serverNow();},1000);if(canUpload)bindTopupProof(t);}
function bindTopupProof(t){let file=null,url=null,pending=null;const input=$('#proof-file');input.onchange=async()=>{try{const next=input.files[0];if(!next)return;await validateProofFile(next);if(url)URL.revokeObjectURL(url);file=next;url=URL.createObjectURL(file);pending=null;$('#proof-preview').innerHTML='<img class="evidence-preview" alt="Preview bukti transfer">';$('#proof-preview img').src=url;$('#remove-proof').hidden=false;}catch(e){file=null;input.value='';fail(e);}};$('#remove-proof').onclick=()=>{if(url)URL.revokeObjectURL(url);file=null;pending=null;input.value='';$('#proof-preview').innerHTML='';$('#remove-proof').hidden=true;};$('#proof-form').onsubmit=async e=>{e.preventDefault();if(paymentUploadBusy||!file)return;paymentUploadBusy=true;const b=$('#send-proof');busy(b,true);input.disabled=true;$('#remove-proof').disabled=true;$('#upload-progress').hidden=false;try{if(!pending){const uuid=crypto.randomUUID(),ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[file.type];pending={id:uuid,path:`${account.user.id}/${t.id}/${uuid}.${ext}`,uploaded:false};}if(!pending.uploaded){await uploadProofXHR(file,pending.path,p=>{$('#upload-progress').value=p;$('#progress-label').textContent=`Mengunggah ${p}%`;});pending.uploaded=true;}await checked(db.rpc('submit_topup_proof',{p_topup_id:t.id,p_proof_id:pending.id,p_storage_path:pending.path}));if(url)URL.revokeObjectURL(url);paymentUploadBusy=false;await topupDetail(t.id);toast('Bukti terkirim. Tunggu ACC admin.');}catch(err){if($('#proof-error'))$('#proof-error').textContent=err.message;fail(err);}finally{paymentUploadBusy=false;busy(b,false);if($('#proof-file'))$('#proof-file').disabled=false;if($('#remove-proof'))$('#remove-proof').disabled=false;}};}
function notificationsPage(){$('#page').innerHTML=`<div class="section-head"><h1>Notifikasi</h1><button class="btn secondary" id="read-notifications">Tandai Semua Dibaca</button></div><div class="notification-list">${account.notifications.map(n=>`<a class="notification-card ${n.read_at?'':'unread'}" href="${esc(n.link.startsWith('#')?n.link:'#transactions')}" data-notification="${n.id}"><span>${icon('bell',21)}</span><div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${formatDate(n.updated_at||n.created_at)}</small></div>${n.read_at?'':'<i></i>'}</a>`).join('')||'<div class="empty">Belum ada notifikasi.</div>'}</div>`;$('#read-notifications').onclick=async()=>{try{await checked(db.rpc('read_notification',{p_id:null}));await loadAccount();notificationsPage();}catch(e){fail(e);}};$$('[data-notification]').forEach(a=>a.addEventListener('click',()=>{checked(db.rpc('read_notification',{p_id:a.dataset.notification})).catch(fail);}));}
function termsPage(){$('#page').innerHTML='<div class="panel"><h1>Syarat Layanan</h1><p>Periksa deskripsi dan screenshot sebelum membeli. Semua pembayaran, top up, dan pembelian memerlukan pemeriksaan admin. Jangan mengunggah password akun atau data pribadi orang lain sebagai bukti.</p><p>YuuZ Wallet adalah kredit internal untuk pembelian di YuuZ Market; tidak bisa ditransfer antar pengguna atau ditarik tunai. Pembelian dengan saldo menahan saldo sampai admin menyetujui atau menolak. Top up hanya menambah saldo setelah ACC atas dana yang diterima.</p><p>Batas pembayaran manual mengikuti deadline transaksi, maksimal 24 jam. Bukti tepat waktu menunggu verifikasi dan tidak otomatis ditolak ketika admin terlambat. Ketentuan garansi mengikuti produk dan pengaturan toko; hubungi admin untuk sengketa atau refund.</p><a class="btn" href="#help">Bantuan Admin</a></div>';}
async function route(){if(paymentUploadBusy){history.replaceState(null,'',activeUserHash);toast('Tunggu pengiriman bukti selesai sebelum berpindah halaman.');return;}activeUserHash=location.hash||'#home';const path=location.hash.replace(/^#/,'').split('?')[0],[page,id]=path.split('/');const protectedPages=['wallet','wallet-history','topup-create','topup','transactions','profile','account-settings','notifications','cart','checkout','order','orders'];if(protectedPages.includes(page)&&!requireLogin(location.hash))return;shell();try{if(!state.ready){$('#page').innerHTML='<div class="skeleton"></div>';return;}if(['login','register','forgot','reset-password'].includes(page))authPage(page);else if(page==='profile')profilePage();else if(page==='account-settings')accountSettings();else if(page==='wallet'||page==='wallet-history')await walletPage(page==='wallet-history');else if(page==='topup-create')topupCreate();else if(page==='topup')await topupDetail(id);else if(page==='transactions'||page==='orders')await transactions();else if(page==='notifications')notificationsPage();else if(page==='terms')termsPage();else if(page==='product')detail(id);else if(page==='products')listPage();else if(page==='categories')$('#page').innerHTML=`<h1>Kategori Produk</h1><div class="category-grid">${state.categories.map(categoryCard).join('')}</div>`;else if(page==='cart')cart();else if(page==='checkout')checkout();else if(page==='order')await orders(id);else if(page==='reviews')reviews();else if(page==='help')help();else home();if(!configured&&!$('#page .setup-notice'))$('#page').insertAdjacentHTML('afterbegin',setupHTML());if(state.loadError)$('#page').insertAdjacentHTML('afterbegin','<div class="notice warning">Data toko belum dapat dimuat. Periksa koneksi, config.js, dan database.sql.</div>');updateAccountBadges();window.scrollTo({top:0,behavior:'auto'});}catch(e){$('#page').innerHTML='<div class="empty"><h3>Halaman belum dapat dimuat</h3><p>Periksa koneksi dan pemasangan SQL versi terbaru, lalu coba lagi.</p><button class="btn secondary" id="retry-page">Coba Lagi</button></div>';$('#retry-page').onclick=route;fail(e);}}
async function initV4(){account.recovery=new URLSearchParams(location.search).get('flow')==='recovery';if(db){db.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY')account.recovery=true;if(event==='TOKEN_REFRESHED'){if(session?.user&&!session.user.is_anonymous)account.user=session.user;return;}if(!['SIGNED_IN','SIGNED_OUT','PASSWORD_RECOVERY','USER_UPDATED'].includes(event))return;setTimeout(async()=>{try{await loadAccount();if(event==='PASSWORD_RECOVERY')location.hash='reset-password';else if(event==='SIGNED_OUT')location.hash='login';else if(['#login','#register'].includes(location.hash)&&signedIn())location.hash=account.next||'#profile';await route();}catch(e){fail(e);}},0);});}
const results=await Promise.allSettled([loadData(),loadAccount()]);for(const r of results)if(r.status==='rejected'){state.loadError=r.reason.message;fail(r.reason);}state.ready=true;if(account.recovery)location.hash='reset-password';await route();if(db){let timer;v4AuthChannel=db.channel('yuuz-v4-user').on('postgres_changes',{event:'*',schema:'public'},()=>{clearTimeout(timer);timer=setTimeout(async()=>{try{await Promise.all([loadData(),loadAccount()]);const page=location.hash.replace(/^#/,'').split(/[/?]/)[0];if(!paymentUploadBusy&&!$('#proof-file')?.files?.length&&!['login','register','forgot','reset-password','account-settings','topup-create','checkout'].includes(page))await route();else updateAccountBadges();}catch(e){fail(e);}},500);}).subscribe();}}

function detail(id){baseDetail(id);const p=state.products.find(p=>p.id===id);if(!p)return;const images=productImages(p);if(!images.length)images.push('assets/logo.svg');const old=$('.gallery-main'),gallery=document.createElement('div');gallery.className='gallery-main hero';gallery.setAttribute('aria-label','Galeri screenshot akun');gallery.innerHTML=`<div class="hero-track">${images.map((u,i)=>`<div class="hero-slide">${imageTag(u,'Foto '+(i+1))}</div>`).join('')}</div><div class="gallery-controls"><button class="icon-btn prev" id="photo-prev" aria-label="Foto sebelumnya">${icon('left')}</button><span class="gallery-count"></span><button class="icon-btn next" id="photo-next" aria-label="Foto berikutnya">${icon('right')}</button></div>`;old.replaceWith(gallery);$('.thumbs').innerHTML=images.map((u,i)=>`<button class="thumb" data-gallery-thumb="${i}" aria-label="Foto ${i+1}">${imageTag(u,'Thumbnail '+(i+1))}</button>`).join('');galleryController=new YuuZCarousel(gallery,{autoplay:false,onChange:n=>{$$('.hero-slide img',gallery).forEach(img=>img.removeAttribute('id'));const active=$$('.hero-slide:not(.clone)',gallery)[n];if(active)$('img',active).id='main-image';$('.gallery-count',gallery).textContent=`${n+1} / ${images.length}`;$$('[data-gallery-thumb]').forEach(b=>b.classList.toggle('active',+b.dataset.galleryThumb===n));}});$$('[data-gallery-thumb]').forEach(b=>b.onclick=()=>galleryController.select(+b.dataset.galleryThumb));gallery.addEventListener('click',e=>{if(!e.target.closest('.hero-slide img'))return;let n=galleryController.logical();const d=modal(`<div class="lightbox">${imageTag(images[n],p.name)}</div><div class="row between"><button class="btn secondary" id="zoom-prev">${icon('left')}</button><span id="zoom-count"></span><button class="btn secondary" id="zoom">Zoom</button><button class="btn secondary" id="zoom-next">${icon('right')}</button></div>`);const show=i=>{n=(i+images.length)%images.length;$('.lightbox img',d).src=safeURL(images[n],'assets/logo.svg');$('#zoom-count').textContent=`${n+1} / ${images.length}`;$('.lightbox',d).classList.remove('zoom');};show(n);$('#zoom-prev').onclick=()=>show(n-1);$('#zoom-next').onclick=()=>show(n+1);$('#zoom').onclick=()=>$('.lightbox',d).classList.toggle('zoom');bindSwipe($('.lightbox',d),direction=>show(n+direction));d.onkeydown=e=>{if(e.key==='ArrowRight')show(n+1);if(e.key==='ArrowLeft')show(n-1);};});}
initV4();
